  'help.send': 'Talebi Gönder',
  'help.ticketSent': 'Talep Gönderildi!',
  'help.ticketSentDesc': 'Talebinizi aldık. Ekibimiz 24 saat içinde e-posta ile yanıt verecektir.',
  'help.close': 'Kapat',
  'help.ticketError': 'Talep gönderme hatası. Lütfen tekrar deneyin.',
  'help.type.cant_login': 'Giriş yapamıyorum',
  'help.type.email_issue': 'E-posta sorunu',
  'help.type.security': 'Güvenlik',
  'help.type.other': 'Diğer',
  'help.faq.cantLogin.q': 'Hesabıma erişemiyorum',
  'help.faq.cantLogin.a': 'Doğru e-posta ve şifreyi kullandığınızdan emin olun. Şifrenizi unuttuysanız, giriş ekranında "Şifremi unuttum?" seçeneğine tıklayın. Sorun devam ederse, bir destek talebi oluşturun.',
  'help.faq.notReceiving.q': 'E-posta almıyorum',
  'help.faq.notReceiving.a': 'Öncelikle Spam klasörünü kontrol edin. Depolamanızın dolu olmadığından emin olun. Sorun devam ederse, gönderenin doğru adresi kullandığını onaylayın ve bir talep oluşturun.',
  'help.faq.cantSend.q': 'E-posta gönderemiyorum',
  'help.faq.cantSend.a': 'İnternet bağlantınızı ve alıcının adresinin doğru olup olmadığını kontrol edin. Eklerin 25MB\'ı aşmadığından emin olun. Birkaç dakika içinde tekrar deneyin.',
  'help.faq.forgotPassword.q': 'Şifremi unuttum',
  'help.faq.forgotPassword.a': 'Giriş ekranında "Şifrenizi mi unuttunuz?" butonuna tıklayın ve şifrenizi kurtarma e-postasıyla sıfırlamak için talimatları izleyin.',
  'help.faq.accountSecurity.q': 'Hesabımın tehlikeye girdiğini düşünüyorum',
  'help.faq.accountSecurity.a': 'Şifrenizi hemen değiştirin. Göndermediğiniz mesajlar için Gönderilenler klasörünü kontrol edin. Ayarlar > Güvenlik kısmında iki aşamalı kimlik doğrulamayı etkinleştirin. Gerekirse acil bir destek talebi oluşturun.',
  'help.faq.appAccess.q': 'Mobil cihazda uygulamaya nasıl erişebilirim?',
  'help.faq.appAccess.a': 'Chatyy\'ye chatyy.com.br adresinden tarayıcıyla erişebilir veya cihazınızın uygulama mağazasından uygulamamızı indirebilirsiniz.',
  'privacy.title': 'Gizlilik Politikası',
  'privacy.subtitle': 'Verilerinizi nasıl koruyoruz ve işliyoruz',
  'privacy.lastUpdated': 'Son güncelleme: Mart 2026',
  'privacy.dataCollection.title': 'Veri Toplama',
  'privacy.dataCollection.body': 'E-posta hizmeti için gerekli olan bilgileri topluyoruz: adınız, e-posta adresiniz ve gönderilen ve alınan mesajların içeriği. Kişisel verilerinizi üçüncü şahıslara pazarlama amacıyla satmıyoruz veya paylaşmıyoruz.',
  'privacy.dataUsage.title': 'Verilerinizi Nasıl Kullanıyoruz',
  'privacy.dataUsage.body': 'Verileriniz yalnızca e-posta hizmetini işletmek ve geliştirmek için kullanılır; mesajların teslimatı, spam filtreleme, AI özellikleri (izin verdiğinizde) ve hesap güvenliği dahil.',
  'privacy.dataSecurity.title': 'Veri Güvenliği',
  'privacy.dataSecurity.body': 'Tüm veriler için endüstri standardı şifreleme (TLS/SSL) kullanıyoruz. Oturumlar, şifrelenmiş token\'lar ve CSRF koruması ile korunmaktadır. Güvenlik uygulamalarımızı düzenli olarak denetliyoruz.',
  'privacy.cookies.title': 'Çerezler ve Yerel Depolama',
  'privacy.cookies.body': 'Oturumunuzu sürdürmek, tercihlerinizi (tema, dil) hatırlamak ve akıcı bir deneyim sağlamak için temel çerezler ve yerel depolama kullanıyoruz. Üçüncü taraf izleme çerezleri kullanmıyoruz.',
  'privacy.thirdParties.title': 'Üçüncü Taraf Hizmetleri',
  'privacy.thirdParties.body': 'AI (Anthropic Claude) ve bildirimler gibi belirli işlevler için üçüncü taraf hizmetleri kullanabiliriz. Bu hizmetler kendi gizlilik politikalarına uyar ve yalnızca gerekli minimum veriyi işler.',
  'privacy.rights.title': 'Haklarınız',
  'privacy.rights.body': 'Her zaman kişisel verilerinize erişme, düzeltme, dışa aktarma veya silme hakkına sahipsiniz. Verilerinizi Ayarlar\'dan veya destek ekibimizle iletişime geçerek yönetebilirsiniz.',
  'privacy.contact.title': 'Bizimle İletişime Geçin',
  'privacy.contact.body': 'Gizlilikle ilgili sorular veya veri talepleri için privacy@chatyy.com.br adresiyle iletişime geçin. 30 gün içinde yanıt vereceğiz.',
  'terms.title': 'Hizmet Şartları',
  'terms.subtitle': 'Chatyy kullanım kılavuzu',
  'terms.lastUpdated': 'Son güncelleme: Mart 2026',
  'terms.acceptance.title': 'Şartların Kabulü',
  'terms.acceptance.body': 'Chatyy\'ye erişerek veya kullanarak bu Hizmet Şartlarını kabul edersiniz. Bu şartların herhangi bir kısmına katılmıyorsanız, hizmeti kullanmayın.',
  'terms.services.title': 'Hizmetlerin Tanımı',
  'terms.services.body': 'Chatyy, e-posta gönderme, alma ve yönetme hizmetleri sunar; ayrıca AI özellikleri, takvim entegrasyonu ve video konferans içerir.',
  'terms.accounts.title': 'Kullanıcı Hesapları',
  'terms.accounts.body': 'Kimlik bilgilerinizi güvende tutmaktan siz sorumlusunuz. Şifrenizi paylaşmayın veya hesabınıza yetkisiz erişime izin vermeyin. Bu hizmeti kullanmak için en az 13 yaşında olmalısınız.',
  'terms.conduct.title': 'Kabul Edilebilir Kullanım',
  'terms.conduct.body': 'Hizmeti spam, kötü amaçlı yazılım, oltalama veya herhangi bir yasadışı içerik göndermek için kullanmamayı kabul edersiniz. Diğer kullanıcıların hesaplarına erişmeye veya hizmetin altyapısını kesintiye uğratmaya çalışmayın.',
  'terms.content.title': 'İçerik Mülkiyeti',
  'terms.content.body': 'Hizmet aracılığıyla oluşturduğunuz ve gönderdiğiniz tüm içeriğin mülkiyetine sahipsiniz. E-postalarınız veya ekleriniz üzerinde mülkiyet iddiasında bulunmuyoruz. Hizmeti sağlamak için içeriği gerektiği şekilde işleyebiliriz.',
  'terms.limitation.title': 'Sorumluluk Sınırlaması',
  'terms.limitation.body': 'Chatyy "olduğu gibi" sunulmaktadır. %99,9 kesintisiz hizmet sağlamayı hedefliyoruz ancak kesintisiz hizmet garantisi vermiyoruz. Hizmetin kullanımından kaynaklanan dolaylı, tesadüfi veya sonuç olarak ortaya çıkan zararlardan sorumlu değiliz.',
  'terms.termination.title': 'Hesap Kapatma',
  'terms.termination.body': 'Bu şartları ihlal eden hesapları askıya alabilir veya kapatabiliriz. Hesabınızı istediğiniz zaman Ayarlar\'dan silebilirsiniz. Kapatıldıktan sonra verileriniz 30 gün içinde silinecektir.',
  'terms.changes.title': 'Şartlarda Değişiklikler',
  'terms.changes.body': 'Bu şartları periyodik olarak güncelleyebiliriz. Önemli değişiklikler hakkında e-posta veya uygulama bildirimleri ile bilgilendireceğiz. Değişikliklerden sonra devam eden kullanım, güncellenmiş şartları kabul ettiğiniz anlamına gelir.',
