  'plans.faqHowFamilyAnswer': 'Ailenden 4 kişiyi ekleyebilirsin. Herkes 500GB depolama alanını paylaşır ve Chatyy One\'ın tüm avantajlarından yararlanır. Her bireyin özel alanı vardır — kimse diğerlerinin dosyalarını göremez.',
  'plans.faqChangePlanAnswer': 'Evet! Plus\'tan Pro\'ya yükseltirsen, sadece orantılı farkı ödeyeceksin. Aşağı düşürürsen, mevcut plan sürenin sonuna kadar devam eder.',
  'plans.faqCardDeclined': 'Kartım reddedildi, ne yapmalıyım?',
  'plans.faqCardDeclinedAnswer': 'Kartını güncellemek için 7 günün var. Bu süre zarfında tüm avantajların çalışmaya devam eder. 7 gün sonra plan ücretsiz plana döner.',
  'plans.faqDataSafe': 'Verilerim güvende mi?',
  'plans.faqDataSafeAnswer': 'Evet! Ödeme verilerin uçtan uca şifreleme ile işlenir. Kart numaranı saklamıyoruz — sadece referans için son 4 hanesini tutuyoruz.',
